// Fonction pour obtenir une traduction
function getDallE3Translation(key, lang) {
    if (dalle3Translations[lang] && dalle3Translations[lang][key]) {
        return dalle3Translations[lang][key];
    }
    // Fallback à l'anglais
    if (dalle3Translations.en && dalle3Translations.en[key]) {
        return dalle3Translations.en[key];
    }
    return null;
}

// Appliquer les traductions dall-e-3
function applyDallE3Translations(lang) {
    console.log('🔥 Applying dall-e-3 translations for:', lang);

    let count = 0;
    document.querySelectorAll('[data-i18n]').forEach(element => {
        const key = element.getAttribute('data-i18n');

        // Seulement pour les clés dall-e-3
        if (key && (key.startsWith('review.dall-e-3.') || key.startsWith('review.common.'))) {
            const translation = getDallE3Translation(key, lang);
            if (translation) {
                element.textContent = translation;
                count++;
            }
        }
    });

    console.log(`✅ Applied ${count} dall-e-3 translations`);
}

// Auto-appliquer quand la langue change
window.addEventListener('languageChanged', (e) => {
    const lang = e.detail.language;
    setTimeout(() => applyDallE3Translations(lang), 200);
});

// Appliquer au chargement
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
        applyDallE3Translations(currentLang);
    });
} else {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyDallE3Translations(currentLang);
}

console.log('✅ dall-e-3 i18n loaded');
